export type RetentionQuestion = {
  code: `R${string}`
  questionVersion: number
  chapterNumber: number
  knowledgeArea: string
  cognitiveLevel: 'B' | 'T' | 'A'
  difficulty: 1 | 2 | 3
  type: 'SINGLE_CHOICE' | 'MULTI_CHOICE'
  criticalConcept: boolean
  legalReview: boolean
  status: 'DRAFT' | 'PUBLISHED'
  learningQuestionStatus: 'DRAFT' | 'PUBLISHED_PROTOTYPE'
  questionText: string
  options: Array<{ value: string; text: string; isCorrect: boolean }>
  correctAnswer: string[]
  correctFeedback: string
  incorrectFeedback: string
}

type Option = readonly [value: string, text: string]
type DraftQuestion = Omit<RetentionQuestion, 'code' | 'questionVersion' | 'status' | 'learningQuestionStatus' | 'options' | 'correctAnswer'> & {
  options: readonly Option[]
  correctAnswer: readonly string[]
}

function item(
  code: `R${string}`, draft: DraftQuestion,
): RetentionQuestion {
  const answerSet = new Set(draft.correctAnswer)
  let hash = 2166136261
  for (const character of code) hash = Math.imul(hash ^ character.charCodeAt(0), 16777619)
  const rotation = (hash >>> 0) % draft.options.length
  const orderedOptions = [...draft.options.slice(rotation), ...draft.options.slice(0, rotation)]
  return {
    ...draft,
    code,
    questionVersion: 1,
    status: 'DRAFT',
    learningQuestionStatus: 'PUBLISHED_PROTOTYPE',
    options: orderedOptions.map(([value, text]) => ({ value, text, isCorrect: answerSet.has(value) })),
    correctAnswer: [...draft.correctAnswer],
  }
}

